      "name": "ATTEMPTS_TO_REPAIR",
      "definition": "A subsequent agent action corrects or re-executes a prior operation in order to resolve an execution failure (e.g., an error, exception, or malformed result) identified in an earlier step.",
      "source_description": "An earlier execution step that produced a failure or error.",
      "target_description": "A subsequent agent action intended to resolve that failure."
    },
    {
      "name": "USES_PRIOR_RESULT_AS_INPUT",
      "definition": "A subsequent agent action consumes an artifact (identifier, path, value, or output element) produced by an earlier execution result, using it as an argument or input to a new operation.",
      "source_description": "An earlier execution result that produced a reusable artifact.",
      "target_description": "A subsequent agent action that invokes an operation using that artifact."
    },
    {
      "name": "RESOLVES_DATA_AMBIGUITY_WITH_REFERENCE_SOURCE",
      "definition": "The agent detects an unknown, placeholder, or ambiguous value within previously retrieved data and queries an additional authoritative or reference source to determine the correct value.",
      "source_description": "Previously retrieved data containing an unknown, placeholder, or ambiguous value.",
      "target_description": "An agent action that retrieves data from an external reference source to resolve the ambiguity."
    }
  ]
}

